/**
 * 双平台 + 海能基座 API 契约（原型 mock 层）
 * ADR-008 五环节：创建 / 资源 / 配置同步 / 对话 / 指标回传
 */
(function (global) {
  var KEYS = {
    registry: 'platform_api_agents',
    configs: 'platform_api_configs',
    metrics: 'platform_api_metrics',
    chats: 'platform_api_chats'
  };

  var TIER_MAP = {
    '标准模型': { pool: 'haineng-general-7b', max_tokens: 4096 },
    '增强模型': { pool: 'haineng-general-32b', max_tokens: 8192 },
    '专业模型': { pool: 'haineng-domain-ft', max_tokens: 8192 },
    '旗舰模型': { pool: 'haineng-flagship', max_tokens: 32768 }
  };

  var useMock = true;

  function read(key, fallback) {
    try {
      var raw = sessionStorage.getItem(key);
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    if (fallback !== undefined) {
      try { sessionStorage.setItem(key, JSON.stringify(fallback)); } catch (e2) {}
      return typeof fallback === 'function' ? fallback() : JSON.parse(JSON.stringify(fallback));
    }
    return null;
  }

  function write(key, val) {
    try { sessionStorage.setItem(key, JSON.stringify(val)); } catch (e) {}
  }

  function delay(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, ms); });
  }

  function nextId(prefix) {
    return prefix + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
  }

  /** ① 同步创建智能体 */
  function syncCreateAgent(payload) {
    payload = payload || {};
    var id = payload.agent_id || nextId('agt');
    var record = {
      agent_id: id,
      name: payload.name || '新智能体',
      type: payload.type || 'qa',
      owner_id: payload.owner_id || 'user_demo',
      scope: payload.scope || 'private',
      status: payload.status || 'dev',
      source: payload.source || 'platform',
      linked: true,
      dev_agent_id: id,
      created_at: new Date().toISOString()
    };
    var list = read(KEYS.registry, []);
    var idx = list.findIndex(function (x) { return x.agent_id === id; });
    if (idx >= 0) list[idx] = Object.assign({}, list[idx], record);
    else list.push(record);
    write(KEYS.registry, list);
    return delay(useMock ? 400 : 0).then(function () {
      return { ok: true, agent_id: id, dev_agent_id: id, linked: true };
    });
  }

  /** ② 获取可用资源 */
  function getAvailableResources(agentId, userId) {
    return delay(useMock ? 200 : 0).then(function () {
      return {
        agent_id: agentId,
        user_id: userId || 'user_demo',
        models: Object.keys(TIER_MAP).map(function (tier) {
          return { tier: tier, quota_remaining: 10000, allowed: true, pool: TIER_MAP[tier].pool };
        }),
        knowledge_bases: [
          { id: 'kb_corp', name: '企业知识库', source: 'haineng' },
          { id: 'kb_party', name: '党建材料库', source: 'haineng' },
          { id: 'kb_qhse', name: 'QHSE制度库', source: 'haineng' }
        ],
        tools: [
          { id: 'tool_erp', name: 'ERP 预算校验', enabled: true }
        ],
        skills: global.Proto && global.Proto.getSkillCatalog
          ? global.Proto.getSkillCatalog().filter(function (s) { return s.status === 'enabled'; }).map(function (s) {
            return { id: s.id, name: s.name };
          })
          : []
      };
    });
  }

  /** ③ 同步配置摘要 */
  function syncConfig(agentId, summary) {
    var map = read(KEYS.configs, {});
    map[agentId] = Object.assign({}, summary || {}, {
      agent_id: agentId,
      synced_at: new Date().toISOString()
    });
    write(KEYS.configs, map);
    return delay(useMock ? 150 : 0).then(function () {
      return { ok: true, agent_id: agentId, summary: map[agentId] };
    });
  }

  function getConfigSummary(agentId) {
    var map = read(KEYS.configs, {});
    return map[agentId] || null;
  }

  /** ④ 发起对话（经海能推理 mock） */
  function startChat(payload) {
    payload = payload || {};
    var traceId = payload.trace_id || nextId('tr');
    var tier = payload.model_tier || '旗舰模型';
    var tierInfo = TIER_MAP[tier] || TIER_MAP['旗舰模型'];
    var log = read(KEYS.chats, []);
    log.push({
      trace_id: traceId,
      agent_id: payload.agent_id,
      model_tier: tier,
      pool: tierInfo.pool,
      at: new Date().toISOString(),
      message_count: (payload.messages || []).length
    });
    if (log.length > 200) log = log.slice(-200);
    write(KEYS.chats, log);
    bumpMetrics(payload.agent_id, { calls: 1, tokens_in: 120, tokens_out: 280, latency_ms: 640 });
    return delay(useMock ? 300 : 0).then(function () {
      return {
        ok: true,
        trace_id: traceId,
        model_tier: tier,
        pool: tierInfo.pool,
        reply: '（海能推理 mock）已基于「' + tier + '」与智能体配置生成回答。'
      };
    });
  }

  /** ⑤ 回传/读取运行指标 */
  function bumpMetrics(agentId, delta) {
    if (!agentId) return;
    var map = read(KEYS.metrics, {});
    var cur = map[agentId] || { calls: 0, tokens_in: 0, tokens_out: 0, latency_ms: 0, error_rate: 0 };
    cur.calls += delta.calls || 0;
    cur.tokens_in += delta.tokens_in || 0;
    cur.tokens_out += delta.tokens_out || 0;
    if (delta.latency_ms) cur.latency_ms = Math.round((cur.latency_ms + delta.latency_ms) / 2);
    cur.updated_at = new Date().toISOString();
    map[agentId] = cur;
    write(KEYS.metrics, map);
  }

  function reportMetrics(agentId, range) {
    var map = read(KEYS.metrics, {});
    var m = map[agentId] || { calls: 0, tokens_in: 0, tokens_out: 0, latency_ms: 0, error_rate: 0.01 };
    return delay(useMock ? 100 : 0).then(function () {
      return Object.assign({}, m, {
        agent_id: agentId,
        range: range || '7d',
        p95_latency_ms: Math.max(m.latency_ms, 820)
      });
    });
  }

  function reportMetricsAll() {
    return read(KEYS.metrics, {});
  }

  global.PlatformApi = {
    useMock: function (v) { useMock = v !== false; },
    TIER_MAP: TIER_MAP,
    syncCreateAgent: syncCreateAgent,
    getAvailableResources: getAvailableResources,
    syncConfig: syncConfig,
    getConfigSummary: getConfigSummary,
    startChat: startChat,
    reportMetrics: reportMetrics,
    reportMetricsAll: reportMetricsAll,
    bumpMetrics: bumpMetrics
  };
})(window);

/**
 * 用户反馈 → 专家任务 → 回流工单 闭环
 * State: proto_ops_work_orders（ADR-008，独立于 proto.js）
 */
(function (global) {
  var WORK_ORDER_KEY = 'proto_ops_work_orders';

  var ROUTE_LABELS = {
    agent_dev: '智能体开发平台',
    knowledge: '知识中心',
    model_svc: '模型服务平台',
    resource: '资源服务中心',
    permission: '系统管理'
  };

  var TYPE_ROUTE = {
    '逻辑推理': 'agent_dev',
    '准确性': 'agent_dev',
    '功能': 'agent_dev',
    '体验': 'agent_dev',
    '数据': 'knowledge',
    '稳定性': 'resource',
    '性能': 'resource'
  };

  function loadOrders() {
    try {
      var raw = sessionStorage.getItem(WORK_ORDER_KEY);
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    return [];
  }

  function saveOrders(list) {
    try { sessionStorage.setItem(WORK_ORDER_KEY, JSON.stringify(list)); } catch (e) {}
  }

  function classifyFeedback(fb) {
    if (!fb) return 'agent_dev';
    return TYPE_ROUTE[fb.type] || 'agent_dev';
  }

  function routeLabel(target) {
    return ROUTE_LABELS[target] || ROUTE_LABELS.agent_dev;
  }

  function nextTaskId() {
    return 'task_' + Date.now().toString(36);
  }

  function nextOrderId() {
    return 'wo_' + Date.now().toString(36);
  }

  /** 从反馈分派创建专家任务 */
  function createTaskFromFeedback(fbId, opts) {
    opts = opts || {};
    if (!global.OpsUserFeedback || !global.OpsExpertWorkbench) return null;
    var fb = OpsUserFeedback.byId(fbId);
    if (!fb) return null;

    var team = opts.team || fb.team || '模型团队';
    var expert = opts.expert || '';
    var deadline = opts.deadline || new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 10);
    var taskId = nextTaskId();

    var task = {
      id: taskId,
      title: '【反馈】' + (fb.title || fb.desc || '用户反馈'),
      status: expert ? 'in_progress' : 'open',
      pool: expert ? 'assigned' : 'public',
      urgent: fb.type === '性能' || fb.type === '稳定性',
      public: !expert,
      team: team,
      deadline: deadline,
      expert: expert,
      feedback_id: fbId,
      agent: fb.agent || '—',
      route_target: classifyFeedback(fb)
    };

    var tasks = OpsExpertWorkbench.loadTasks();
    tasks.unshift(task);
    OpsExpertWorkbench.saveTasks(tasks);

    var list = OpsUserFeedback.load().map(function (x) {
      if (x.id !== fbId) return x;
      return Object.assign({}, x, {
        status: 'processing',
        task_id: taskId,
        team: team,
        expert: expert || x.expert
      });
    });
    OpsUserFeedback.save(list);

    if (global.OpsMessageCenter && OpsMessageCenter.pushTodo) {
      OpsMessageCenter.pushTodo({
        title: expert ? '专家任务已分派：' + task.title : '团队任务已创建：' + task.title,
        href: expert
          ? OpsShell.href('12-expert-task-detail.html', { taskId: taskId })
          : OpsShell.href('12-expert-workbench.html')
      });
    }

    return task;
  }

  /** 专家完成任务 → 生成回流工单 */
  function createWorkOrderFromTask(taskId, summary) {
    if (!global.OpsExpertWorkbench) return null;
    var task = OpsExpertWorkbench.taskById(taskId);
    if (!task) return null;

    var target = task.route_target || 'agent_dev';
    var order = {
      id: nextOrderId(),
      task_id: taskId,
      feedback_id: task.feedback_id || '',
      title: '回流：' + (task.title || '专家任务'),
      route_target: target,
      route_label: routeLabel(target),
      status: 'open',
      summary: summary || '专家已完成分析，请相关平台跟进优化。',
      agent: task.agent,
      created_at: new Date().toISOString().slice(0, 16).replace('T', ' ')
    };

    var orders = loadOrders();
    orders.unshift(order);
    saveOrders(orders);

    if (task.feedback_id && global.OpsUserFeedback) {
      var fbs = OpsUserFeedback.load().map(function (x) {
        if (x.id !== task.feedback_id) return x;
        return Object.assign({}, x, { status: 'resolved', work_order_id: order.id });
      });
      OpsUserFeedback.save(fbs);
    }

    return order;
  }

  function getOrders(limit) {
    var list = loadOrders();
    if (limit) return list.slice(0, limit);
    return list;
  }

  function deepLinkForOrder(order) {
    if (!order) return '#';
    var map = {
      agent_dev: '06-dev-editor.html?id=agt_demo_001',
      knowledge: '#',
      model_svc: '#',
      resource: '14-resource-dashboard.html',
      permission: '13-permission-mgmt.html'
    };
    return map[order.route_target] || '14-business-dashboard.html';
  }

  global.OpsFeedbackLoop = {
    WORK_ORDER_KEY: WORK_ORDER_KEY,
    classifyFeedback: classifyFeedback,
    routeLabel: routeLabel,
    createTaskFromFeedback: createTaskFromFeedback,
    createWorkOrderFromTask: createWorkOrderFromTask,
    getOrders: getOrders,
    deepLinkForOrder: deepLinkForOrder,
    loadOrders: loadOrders,
    saveOrders: saveOrders
  };
})(window);

/**
 * 运营看板四件套：业务 / 模型 / 资源 / 用户与智能体画像
 */
(function (global) {
  var DEMO = {
    business: {
      kpis: [
        { label: '日活用户', value: '1,284', delta: '+12%' },
        { label: '智能体会话', value: '8,420', delta: '+8%' },
        { label: '待处理反馈', value: '18', delta: '-3' },
        { label: '回流工单', value: '6', delta: '+2' }
      ],
      topAgents: [
        { name: '海能·智能助手', calls: 3240, satisfaction: '92%' },
        { name: '党建智能助手', calls: 1820, satisfaction: '88%' },
        { name: '钻完井报告助手', calls: 960, satisfaction: '85%' }
      ]
    },
    model: {
      kpis: [
        { label: '总调用量', value: '42.6K', delta: '+5%' },
        { label: '平均 Token/次', value: '1,240', delta: '-2%' },
        { label: '失败率', value: '1.2%', delta: '-0.3%' },
        { label: '旗舰档占比', value: '18%', delta: '+1%' }
      ],
      tiers: [
        { tier: '标准模型', calls: 18200, pct: 43 },
        { tier: '增强模型', calls: 12400, pct: 29 },
        { tier: '专业模型', calls: 8200, pct: 19 },
        { tier: '旗舰模型', calls: 3800, pct: 9 }
      ]
    },
    resource: {
      kpis: [
        { label: 'Token 消耗', value: '12.8M', delta: '+6%' },
        { label: 'P95 延迟', value: '820ms', delta: '-40ms' },
        { label: 'GPU 利用率', value: '67%', delta: '+4%' },
        { label: '配额告警', value: '2', delta: '0' }
      ],
      pools: [
        { pool: 'haineng-general-7b', util: 54, tokens: '4.2M' },
        { pool: 'haineng-general-32b', util: 72, tokens: '5.1M' },
        { pool: 'haineng-domain-ft', util: 61, tokens: '2.4M' },
        { pool: 'haineng-flagship', util: 83, tokens: '1.1M' }
      ]
    },
    profile: {
      kpis: [
        { label: '画像覆盖用户', value: '892', delta: '+15' },
        { label: '高频用户', value: '126', delta: '+4' },
        { label: '沉默用户', value: '48', delta: '-6' },
        { label: '跨智能体用户', value: '203', delta: '+11' }
      ],
      segments: [
        { name: '财务报销高频', users: 86, agents: ['差旅报销助手'] },
        { name: 'QHSE 专业', users: 64, agents: ['钻完井安全', 'jsa文档生成'] },
        { name: '党建材料', users: 112, agents: ['党建智能助手'] }
      ]
    }
  };

  function renderKpis(containerId, kpis) {
    var el = document.getElementById(containerId);
    if (!el) return;
    el.innerHTML = kpis.map(function (k) {
      return '<div class="ops-dash-kpi"><div class="ops-dash-kpi-label">' + k.label + '</div>' +
        '<div class="ops-dash-kpi-value">' + k.value + '</div>' +
        '<div class="ops-dash-kpi-delta">' + k.delta + '</div></div>';
    }).join('');
  }

  function renderBarRows(containerId, rows, labelKey, valueKey, pctKey) {
    var el = document.getElementById(containerId);
    if (!el) return;
    el.innerHTML = rows.map(function (r) {
      var pct = pctKey ? r[pctKey] : 0;
      return '<div class="ops-dash-bar-row">' +
        '<div class="ops-dash-bar-head"><span>' + r[labelKey] + '</span><span>' + r[valueKey] + '</span></div>' +
        (pctKey ? '<div class="ops-dash-bar-track"><div class="ops-dash-bar-fill" style="width:' + pct + '%"></div></div>' : '') +
        '</div>';
    }).join('');
  }

  function renderWorkOrders(containerId) {
    var el = document.getElementById(containerId);
    if (!el || !global.OpsFeedbackLoop) return;
    var orders = OpsFeedbackLoop.getOrders(8);
    if (!orders.length) {
      el.innerHTML = '<p style="font-size:13px;color:var(--text-muted);">暂无回流工单。完成专家任务后将自动生成。</p>';
      return;
    }
    el.innerHTML = '<table class="data-table"><thead><tr><th>工单</th><th>回流目标</th><th>状态</th><th>时间</th><th></th></tr></thead><tbody>' +
      orders.map(function (o) {
        return '<tr><td><strong>' + o.title + '</strong><div style="font-size:11px;color:var(--text-muted);">' + (o.agent || '—') + '</div></td>' +
          '<td><span class="tag tag-info">' + o.route_label + '</span></td>' +
          '<td><span class="tag tag-warn">' + o.status + '</span></td>' +
          '<td style="color:var(--text-muted);font-size:12px;">' + o.created_at + '</td>' +
          '<td><a href="' + OpsFeedbackLoop.deepLinkForOrder(o) + '" class="btn btn-sm">前往</a></td></tr>';
      }).join('') + '</tbody></table>';
  }

  function mergePlatformMetrics() {
    if (!global.PlatformApi) return;
    var all = PlatformApi.reportMetricsAll();
    var totalCalls = 0;
    Object.keys(all).forEach(function (k) { totalCalls += all[k].calls || 0; });
    if (totalCalls > 0) {
      DEMO.business.kpis[1].value = String(totalCalls);
      DEMO.model.kpis[0].value = String(totalCalls);
    }
  }

  function initBusinessPage() {
    OpsShell.initShell({ module: 'dashboard', subtitle: '业务看板' });
    mergePlatformMetrics();
    renderKpis('dashKpis', DEMO.business.kpis);
    renderBarRows('dashTopAgents', DEMO.business.topAgents.map(function (a) {
      return { name: a.name, calls: a.calls + ' 次 / ' + a.satisfaction, pct: Math.min(100, Math.round(a.calls / 40)) };
    }), 'name', 'calls', 'pct');
    renderWorkOrders('dashWorkOrders');
  }

  function initModelPage() {
    OpsShell.initShell({ module: 'dashboard', subtitle: '模型看板' });
    mergePlatformMetrics();
    renderKpis('dashKpis', DEMO.model.kpis);
    renderBarRows('dashTiers', DEMO.model.tiers, 'tier', 'calls', 'pct');
  }

  function initResourcePage() {
    OpsShell.initShell({ module: 'dashboard', subtitle: '资源看板' });
    renderKpis('dashKpis', DEMO.resource.kpis);
    renderBarRows('dashPools', DEMO.resource.pools.map(function (p) {
      return { pool: p.pool, meta: p.tokens + ' · ' + p.util + '%', pct: p.util };
    }), 'pool', 'meta', 'pct');
  }

  function initProfilePage() {
    OpsShell.initShell({ module: 'dashboard', subtitle: '用户与智能体画像' });
    renderKpis('dashKpis', DEMO.profile.kpis);
    var el = document.getElementById('dashSegments');
    if (el) {
      el.innerHTML = DEMO.profile.segments.map(function (s) {
        return '<div class="card" style="padding:14px;margin-bottom:10px;">' +
          '<strong>' + s.name + '</strong> <span class="tag tag-info">' + s.users + ' 人</span>' +
          '<p style="font-size:12px;color:var(--text-muted);margin-top:8px;">常用：' + s.agents.join('、') + '</p></div>';
      }).join('');
    }
  }

  global.OpsDashboards = {
    initBusinessPage: initBusinessPage,
    initModelPage: initModelPage,
    initResourcePage: initResourcePage,
    initProfilePage: initProfilePage
  };
})(window);

